import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, positionLocal, normalLocal, uniform, smoothstep, length, sub, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group, Mesh, PlaneGeometry, BoxGeometry, RingGeometry, Color,
    DirectionalLight, PointLight, Texture, DoubleSide, SRGBColorSpace
  } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };

  const group = new Group();
  group.name = 'quote-panel-home';

  const timelines = [];
  const disposables = [];
  const primitiveHandles = [];

  // ---------- local backdrop card (avoid flat void behind the panel) ----------
  const backdropGeo = new PlaneGeometry(3.9, 2.7);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  const inkColor = new Color(colors.ink);
  const surfaceColor = new Color(colors.surface);
  backdropMat.colorNode = uv().y.mix
    ? uv().y // fallback (unused branch, kept for safety)
    : undefined;
  // build a vertical gradient manually since mix() node needed
  const vUv = uv();
  const gradTop = uniform(inkColor);
  const gradBottom = uniform(surfaceColor);
  backdropMat.colorNode = gradBottom.mix(gradTop, vUv.y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.12);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- machined metal frame ----------
  const frameGeo = new BoxGeometry(3.55, 2.25, 0.06);
  const frameMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4
  });
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.set(0, 0, -0.06);
  group.add(frame);
  disposables.push(frameGeo, frameMat);

  // ---------- parallax image plane (tessellated + depth displacement) ----------
  const PANEL_W = 3.4;
  const PANEL_H = 2.1;
  const panelGeo = new PlaneGeometry(PANEL_W, PANEL_H, 64, 64);

  const placeholderColorTex = new Texture();
  const placeholderDepthTex = new Texture();
  const colorMapNode = texture(placeholderColorTex, uv());
  const depthMapNode = texture(placeholderDepthTex, uv());
  const dispStrength = uniform(0.18);

  const panelMat = new MeshStandardNodeMaterial({ side: DoubleSide });
  panelMat.colorNode = colorMapNode;
  panelMat.roughnessNode = uniform(0.6);
  panelMat.metalnessNode = uniform(0.15);
  panelMat.positionNode = positionLocal.add(
    normalLocal.mul(depthMapNode.r.sub(0.5).mul(dispStrength))
  );

  const panel = new Mesh(panelGeo, panelMat);
  panel.position.set(0, 0.05, 0.02);
  group.add(panel);
  disposables.push(panelGeo, panelMat, placeholderColorTex, placeholderDepthTex);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (SRGBColorSpace) tex.colorSpace = SRGBColorSpace;
      colorMapNode.value = tex;
      panelMat.needsUpdate = true;
    }).catch(() => {});
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthMapNode.value = tex;
      panelMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---------- accent bar (quote mark / attribution rule) ----------
  const accentBarGeo = new BoxGeometry(0.05, 2.0, 0.05);
  const accentBarMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    roughness: 0.4,
    metalness: 0.2,
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.6
  });
  const accentBar = new Mesh(accentBarGeo, accentBarMat);
  accentBar.position.set(-1.78, 0.05, 0.08);
  group.add(accentBar);
  disposables.push(accentBarGeo, accentBarMat);

  const ruleGeo = new BoxGeometry(1.4, 0.02, 0.02);
  const ruleMat = new MeshBasicNodeMaterial({ color: new Color(colors.paper) });
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(-0.5, -0.82, 0.08);
  group.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // ---------- contact shadow ----------
  const shadowGeo = new PlaneGeometry(4.2, 4.2, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const distNode = length(sub(uv(), vec2(0.5, 0.5)));
  shadowMat.colorNode = uniform(new Color('#000000'));
  shadowMat.opacityNode = smoothstep(0.5, 0.0, distNode).mul(0.5);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.55, 0.3);
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------- node-local lighting (rim / accent) ----------
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.9);
  rimLight.position.set(-2.2, 1.4, 1.6);
  group.add(rimLight);

  const accentPoint = new PointLight(new Color(colors.accent), 0.6, 4, 2);
  accentPoint.position.set(-1.6, 0.2, 0.6);
  group.add(accentPoint);

  disposables.push(rimLight, accentPoint);

  // ---------- entrance: weighted settle ----------
  group.scale.setScalar(1.04);
  const baseY = group.position.y;
  group.position.y = baseY - 0.3;
  const entranceTl = gsap.timeline();
  entranceTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
  entranceTl.to(group.position, { y: baseY, duration: 0.7, ease: 'power3.out' }, 0);
  timelines.push(entranceTl);

  // ---------- cinematic primitives ----------
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const prim of primitiveConfigs) {
    const fn = ctx.primitives?.[prim.name];
    if (!fn) continue;
    let target = group;
    if (prim.name === 'parallax-scroll') target = panel;
    const handle = fn(target, { ...(prim.params ?? {}), trigger: prim.trigger });
    if (handle) primitiveHandles.push(handle);
  }

  // ---------- interactions ----------
  const baseGroupY = group.position.y;
  let hoverTween = null;

  function onPointerEnter() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseGroupY + 0.15,
      duration: 0.3,
      ease: 'power3.out'
    });
    timelines.push(hoverTween);
  }

  function onPointerLeave() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseGroupY,
      duration: 0.3,
      ease: 'power3.out'
    });
    timelines.push(hoverTween);
  }

  function onClick() {
    const pressTl = gsap.timeline();
    pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    pressTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power2.out' });
    timelines.push(pressTl);
    ctx.emit('hub-home.select', { id: config.id ?? 'home-quote-panel' });
  }

  group.userData.handlers = {
    onPointerEnter,
    onPointerLeave,
    onClick
  };

  // ---------- cleanup ----------
  group.userData.cleanup = () => {
    for (const tl of timelines) {
      if (tl && tl.kill) tl.kill();
    }
    for (const h of primitiveHandles) {
      if (h && h.cleanup) h.cleanup();
    }
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
  };

  return group;
}
